text:
{
  "questions": [
    {
      "n": 1,
      "start": "Ist der Regierungsrat nicht auch der Meinung,",
      "end": "dass Projekte wie oben erwähnt anhand einer Kosten-/Nutzenanalyse und unter dem Blickwinkel der finanziellen Ausgangslage zu überprüfen sind?"
    },
    {
      "n": 2,
      "start": "Wird vom Gesamtregierungsrat eine Strategie zur Kostensenkung verfolgt?",
      "end": "Wie sieht diese Strategie aus und wann kann man mit der konkreten Umsetzung rechnen?"
    },
    {
      "n": 3,
      "start": "Ist der Regierungsrat nicht auch der Meinung, dass bei der Ausarbeitung eines substanziellen Entlastungspaketes",
      "end": "zeitliche Dringlichkeit besteht und sehr konsequent Kosten eingespart werden müssen?"
    },
    {
      "n": 4,
      "start": "Hat der Regierungsrat intern eine nachvollziehbare und vollständige Vollkostenrechnung der durch die geplanten Projekte wiederkehrenden jährlichen Ausgaben erstellt?",
      "end": "Wie sieht diese Rechnung aus und in welchem Ausmass wird der Finanzplan dadurch tangiert, respektive in welchem Ausmass werden die jährlichen Ausgaben in der Zukunft erhöht? Liegt jeweils eine entsprechende nachvollziehbare Kosten-/Nutzenanalyse vor?"
    },
    {
      "n": 5,
      "start": "Ist der Regierungsrat nicht auch der Meinung, wie dies pikanterweise anlässlich der PHSH-Debatte von Regierungsrat Amsler anlässlich der letzten Kantonsratssitzung vermerkt wurde,",
      "end": "dass der kleine Kanton Schaffhausen sich nicht alles leisten kann? Wäre es nicht von Nöten, sich auf die Kernaufgaben zu konzentrieren respektive diese Kernaufgaben endlich zu definieren? Wann wird dem Kantonsrat gegebenenfalls die Aufstellung der Kernaufgaben präsentiert?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Der Kantonsrat ist mit der Ergänzungsvorlage vom 19. April 2011 zur Steuergesetzvorlage,",
      "end": "der schriftlichen Beantwortung der Interpellationen 2011/1 und 2011/2 der Kantonsrätinnen Martina Munz und Sabine Spross sowie bei der Beratung über die Staatsrechnung 2010 über die Entwicklung der Staatseinnahmen und ihre Auswirkungen auf den Kantonshaushalt orientiert worden."
    },
    {
      "n": 2,
      "start": "Selbstverständlich wird eine Strategie zur Entlastung des Kantonshaushaltes verfolgt.",
      "end": "Der Regierungsrat wird dem Kantonsrat im 1. Semester 2012 seine Entlastungsmassnahmen zur Beschlussfassung unterbreiten."
    },
    {
      "n": 3,
      "start": "Die Arbeiten an einem Entlastungspaket sind im Gange.",
      "end": null
    },
    {
      "n": 4,
      "start": "Es muss unterschieden werden zwischen Projekten in der Vorbereitungsphase und solchen, die dem Kantonsrat zur Beratung und Beschlussfassung unterbreitet werden.",
      "end": "Es ist somit der Kantonsrat, welcher mit seiner Beschlussfassung die Prioritäten setzt."
    },
    {
      "n": 5,
      "start": "In den Art. 79 bis 95 der Kantonsverfassung hat das Volk des Kantons Schaffhausen die verfassungsmässigen öffentlichen Aufgaben festgelegt.",
      "end": "Es ist somit der Kantonsrat, welcher mit seiner Beschlussfassung die Prioritäten setzt."
    }
  ],
  "submitter": "Andreas Gnädinger",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "Der Kantonsrat beschliesst über den Staatsvoranschlag und neue Ausgaben (Art. 56 lit. a und d der Kantonsverfassung, KV, SHR 101.000).",
    "end": "Die Entscheide obliegen dem Kantonsrat."
  }
}
